#!/usr/bin/env bash
# Differential check of the phase-2 helpers (lower_types.cpp, run by build/pathb-ptx-emit --eval-cases) against the Ruby
# reference in scripts/pathb-ptx-emit.rb. The Ruby side is generated from that file's own functions (the reader and type
# helpers, copied verbatim), then lower-types-driver.rb, so the reference cannot drift from the script.
# Cases come from testdata/lower-types-edge.cases and from the (type, const, global) forms of the IR files given as
# arguments (default: build/sweep3/*.ir under 8 MB), generated by gen-lower-cases-driver.rb.
# Usage: diff-lower-types.sh [FILE.ir]...
set -u
root=$(cd "$(dirname "$0")/../.." && pwd)
here=$root/tools/pathb-ptx-emit
main=$(cd "$(dirname "$(git -C "$root" rev-parse --git-common-dir)")" && pwd)
mrb=${MRB:-$root/build/mruby-tool/bin/mruby}
[ -x "$mrb" ] || mrb=$main/build/mruby-tool/bin/mruby
cxx=${PTX_EMIT:-$root/build/pathb-ptx-emit}
ref=$root/scripts/pathb-ptx-emit.rb
[ -x "$cxx" ] || { echo "diff-lower-types: $cxx not built (make -C tools/pathb-ptx-emit)"; exit 1; }
[ -x "$mrb" ] || { echo "diff-lower-types: no mruby (set MRB)"; exit 1; }
work=$(mktemp -d)

# The Ruby functions: the reader and type helpers (class Refused .. before the special registers, which the helpers do
# not use), then strip_comments and parse_forms_chunked (the phase-1 reader the case files are read with).
a=$(grep -n '^class Refused' "$ref" | cut -d: -f1)
b=$(grep -n '^# The special registers of the GPU' "$ref" | cut -d: -f1)
c=$(grep -n '^def strip_comments' "$ref" | cut -d: -f1)
d=$(grep -n '^def emit_module' "$ref" | cut -d: -f1)
head_text() {
  echo "# generated by tools/pathb-ptx-emit/diff-lower-types.sh from scripts/pathb-ptx-emit.rb"
  sed -n "${a},$((b-1))p" "$ref"
  sed -n "${c},$((d-1))p" "$ref"
}
{ head_text; cat "$here/lower-types-driver.rb"; } > "$work/eval.rb"
{ head_text; cat "$here/gen-lower-cases-driver.rb"; } > "$work/gen.rb"

if [ $# -gt 0 ]; then
  files=("$@")
else
  files=()
  for f in "$root"/build/sweep3/*.ir "$main"/build/sweep3/*.ir; do
    [ -f "$f" ] || continue
    [ "$(wc -c < "$f")" -le 8000000 ] && files+=("$f")
  done
fi

# Cases: the committed edge file first, then the forms of the IR files.
cp "$here/testdata/lower-types-edge.cases" "$work/cases.txt"
if [ ${#files[@]} -gt 0 ]; then
  "$mrb" "$work/gen.rb" "${files[@]}" > "$work/gen.txt" 2> "$work/gen.err" || {
    echo "diff-lower-types: case generation failed"; head -5 "$work/gen.err"; exit 1; }
  cat "$work/gen.txt" >> "$work/cases.txt"
fi
# The head of each case (its function name), one per line, for the per-function counts.
grep -o '^(\S*' "$work/cases.txt" | sed 's/^(//' > "$work/heads.txt"
n_cases=$(wc -l < "$work/cases.txt")

"$cxx" --eval-cases "$work/cases.txt" > "$work/c.out" 2> "$work/c.err"; cr=$?
"$mrb" "$work/eval.rb" "$work/cases.txt" > "$work/r.out" 2> "$work/r.err"; rr=$?
if [ $cr -ne 0 ] || [ $rr -ne 0 ]; then
  echo "diff-lower-types: exit cxx=$cr ruby=$rr"; head -3 "$work/c.err" "$work/r.err"
fi
if [ "$(wc -l < "$work/r.out")" -ne "$(wc -l < "$work/c.out")" ] || [ "$(wc -l < "$work/c.out")" -ne "$n_cases" ]; then
  echo "diff-lower-types: line counts differ (cases $n_cases, ruby $(wc -l < "$work/r.out"), cxx $(wc -l < "$work/c.out"))"
  exit 1
fi

# Per-function counts: cases, and cases whose two outputs differ (with the first difference).
paste -d'\t' "$work/heads.txt" "$work/r.out" "$work/c.out" | awk -F'\t' '
  { n[$1]++ }
  $2 != $3 { bad[$1]++; if (!($1 in first)) first[$1] = NR ": ruby=" $2 " cxx=" $3 }
  END {
    for (k in n) printf "%-22s %6d cases %5d differ%s\n", k, n[k], bad[k] + 0, (k in first ? "   first: " first[k] : "")
  }' | sort
total_bad=$(paste -d'\t' "$work/r.out" "$work/c.out" | awk -F'\t' '$1 != $2' | wc -l)
echo "diff-lower-types: $n_cases cases, $total_bad different (work dir $work)"
[ "$total_bad" -eq 0 ]
